# Kokoro speaks ~2.15 words a second at rate 100 including pauses; speed up long scripts to land under 58 s
def rate(c): w = sum(len(l.split()) for l in c["lines"]); return max(100, -(-round(w / 2.15 / 58 * 100)))

def script(i, c):
    reg = c.get("region", c["slug"]); bb = None if "region" in c else c["bbox"]
    z = c.get("zoom", 1)
    m = lambda zoom=1, **kw: dict(dict(region=reg, hl=[c["hl"]], zoom=zoom * z, **({"bbox": bb} if bb else {})), **kw)
    L = c["lines"]
    shots = [
        ["map_region", m(pulse=c["hub"], lights=1, towers=0, tag=c["tag"]), L[0]],
        ["map_region", m(lights=1, towers=1, pins=c["pins"]), L[1]],
        ["map_region", m(lights=1, towers=0, river=c["rivers"], pins=c["pins"][:2], **({"seam": c["seam"]} if "seam" in c else {})), L[2]],
        ["city_grow", {"phase": 1}, L[3]],
        ["map_region", m(lights=1, towers=1, pins=c["pins"][1:] if len(c["pins"]) > 2 else c["pins"], pulse=next(p[:2] for p in c["pins"] if p[2] == c["focus"]), zoom=.9), L[4]],
        ["tower_field", {"superstar": 1, "endcard": c["short"]}, L[5]],
    ]
    return {"series": "Where the Money Lives: Shorts", "episode": i + 1, "title": f"Where {c['short']} Money Lives", "format": "short",
            "voice": "kokoro:bm_george", "rate": rate(c), "sections": [{"name": c["name"], "lines": shots}]}

if __name__ == "__main__":
    here = os.path.dirname(os.path.abspath(__file__))
    for i, c in enumerate(C):
        d = f"{here}/{i + 1:02d}-{c['slug']}"; os.makedirs(d, exist_ok=True)
        json.dump(script(i, c), open(f"{d}/script.json", "w"), indent=1, ensure_ascii=False)
        print(d.split('/')[-1], sum(len(l.split()) for l in c["lines"]), "words")
